class Solution {
    public int distinctAverages(int[] nums){
        Arrays.sort(nums);
        Set<Integer> sums=new HashSet<>();
        for(int left=0,right=nums.length-1;left<right;left++,right--)sums.add(nums[left]+nums[right]);
        return sums.size();
    }
}

code.kotlin:
class Solution {
    fun distinctAverages(nums:IntArray):Int{
        nums.sort();
        val sums=HashSet<Int>();
        var left=0;
        var right=nums.lastIndex;
        while(left<right)sums.add(nums[left++]+nums[right--]);
        return sums.size
    }
}

code.cpp:
class Solution {
    public:int distinctAverages(vector<int>& nums){
        sort(nums.begin(),nums.end());
        unordered_set<int> sums;
        for(int left=0,right=nums.size()-1;left<right;++left,--right)sums.insert(nums[left]+nums[right]);
        return sums.size();
    }
};
